import{_ as o,c as t,o as a,aj as s}from"./chunks/framework.Id7s26SP.js";const b=JSON.parse('{"title":"Interface: Db3RetentionPolicy","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/Db3RetentionPolicy.md","filePath":"reference/js-bao-wss-client/api/interfaces/Db3RetentionPolicy.md"}'),n={name:"reference/js-bao-wss-client/api/interfaces/Db3RetentionPolicy.md"};function r(c,e,i,d,l,p){return a(),t("div",null,[...e[0]||(e[0]=[s('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / Db3RetentionPolicy</p><h1 id="interface-db3retentionpolicy" tabindex="-1">Interface: Db3RetentionPolicy <a class="header-anchor" href="#interface-db3retentionpolicy" aria-label="Permalink to “Interface: Db3RetentionPolicy”">​</a></h1><p>The client&#39;s one retention policy, as <code>client.db3.setRetentionPolicy</code> takes it: what a sweep keeps on the device. A db3 with writes the room has not judged is never removed by a sweep.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="default" tabindex="-1">default <a class="header-anchor" href="#default" aria-label="Permalink to “default”">​</a></h3><blockquote><p><strong>default</strong>: <code>&quot;persist&quot;</code> | <code>&quot;session&quot;</code></p></blockquote><p><code>persist</code> keeps local copies across sessions; <code>session</code> removes them at sign-out.</p><hr><h3 id="maxbytes" tabindex="-1">maxBytes? <a class="header-anchor" href="#maxbytes" aria-label="Permalink to “maxBytes?”">​</a></h3><blockquote><p><code>optional</code> <strong>maxBytes?</strong>: <code>number</code></p></blockquote><p>The most bytes of local document data kept. A db3 copy has no recorded size, so this never removes one.</p><hr><h3 id="maxdocs" tabindex="-1">maxDocs? <a class="header-anchor" href="#maxdocs" aria-label="Permalink to “maxDocs?”">​</a></h3><blockquote><p><code>optional</code> <strong>maxDocs?</strong>: <code>number</code></p></blockquote><p>The most db3 copies kept on this device (what <code>stored()</code> lists), subscribed ones included; the least recently opened go first. A subscribed copy, one with unsent writes, one held open, a pending create and one another tab holds are never removed and still count, so more may stay. <code>0</code> or absent: no cap.</p><hr><h3 id="preserveonsignout" tabindex="-1">preserveOnSignOut? <a class="header-anchor" href="#preserveonsignout" aria-label="Permalink to “preserveOnSignOut?”">​</a></h3><blockquote><p><code>optional</code> <strong>preserveOnSignOut?</strong>: <code>boolean</code></p></blockquote><p>Keep local data at sign-out even under <code>session</code>.</p><hr><h3 id="ttlms" tabindex="-1">ttlMs? <a class="header-anchor" href="#ttlms" aria-label="Permalink to “ttlMs?”">​</a></h3><blockquote><p><code>optional</code> <strong>ttlMs?</strong>: <code>number</code></p></blockquote><p>How long a document not opened is kept, in ms.</p>',25)])])}const m=o(n,[["render",r]]);export{b as __pageData,m as default};
